/* 状态模拟：真实规则是 .row:is(:hover, [aria-expanded='true']) .diffAdded / .diffRemoved */
.row.forceHover .diffAdded { color: var(--dsw-alias-state-success-primary); }
.row.forceHover .diffRemoved { color: var(--dsw-alias-state-error-primary); }

/* 状态模拟：真实规则是 .root:hover .iconIdle { opacity: 0 } / .root:hover .chevronHover { opacity: 1 } */
.root.forceHover .iconIdle { opacity: 0; }
.root.forceHover .chevronHover { opacity: 1; }
/* 状态模拟：真实动画是 1.5s steps(48, end) 无限循环；示例把扫光停在中段 */
.sweep, .highlight { animation: none; transform: translateX(0); }
